# ───────── 3. Давление в шинах зимой (лёгкая) ─────────
def _pres14(p0, t0, t):
    return (p0 + 1.013) * (t + 273.15) / (t0 + 273.15) - 1.013
_fmt14 = lambda x: f"{x:.1f}".replace(".", ",")
_rows14 = [[f"{t:+d} °C".replace("+0", "0").replace("-", "−"), _fmt14(_pres14(2.0, 20, t)), _fmt14(_pres14(2.2, 20, t))] for t in (20, 10, 0, -10, -20, -30)]

